<?php
$d=$dashboard;$hasShop=(bool)$user['shop_id'];
$restricted=fn(string $scope)=>!$hasShop?'No shop selected':(!$d['access'][$scope]?'Permission required':null);
$inventoryHint=$d['untracked_count'] ? $d['untracked_count'].' active products await a stock balance' : ($d['balance_count']?'From recorded stock balances':'No stock balances recorded');
$metrics=[
 ['Today’s revenue','sale',$d['sales_today']!==null?money($d['sales_today']['revenue']):null,$restricted('finance')??'Sales not set up','Products + labour, excl. GST; net of cancellations'],
 ['Bills today','receipt',$d['sales_today']['invoice_count']??null,$restricted('finance')??'Sales not set up','Issued today; revenue includes cancellation reversals'],
 ['Active products','box',$d['products'],$restricted('catalogue') ?? (isset($d['errors']['catalogue'])?'Temporarily unavailable':'Catalogue not set up'),'Active, unarchived products'],
 ['Low-stock products','stock',$d['low_stock_count'],$restricted('stock') ?? (isset($d['errors']['stock'])?'Temporarily unavailable':'Stock not set up'),$d['untracked_count']?$d['untracked_count'].' products await stock balances':'At or below a configured minimum'],
 ['Stock valuation','layers',$d['valuation']!==null?money($d['valuation']):null,$restricted('finance') ?? (isset($d['errors']['stock'])?'Temporarily unavailable':'Stock not set up'),$inventoryHint],
 ['Customer outstanding','users',null,'Payments not set up','Available with customer accounts'],
 ['Supplier outstanding','truck',null,'Purchases not set up','Available with supplier accounts'],
];
?>
<section class="page-heading"><div><h1>Dashboard</h1><p class="welcome-note"><?= e($shopName) ?> <span aria-hidden="true">·</span> Hello, <?= e($user['name']) ?>.</p></div><div class="date-label"><?= icon('calendar') ?><time datetime="<?= $date->format('Y-m-d') ?>"><?= $date->format('D, d M Y') ?></time></div></section>
<?php if (!$hasShop): ?><div class="info-strip"><?= icon('info') ?><span>You’re signed in as a platform administrator. Shop metrics appear in a shop owner’s workspace.</span></div><?php endif; ?>
<?php if ($d['errors']): ?><div class="alert" role="alert">Some dashboard information couldn’t be loaded. Refresh to try again.</div><?php endif; ?>
<section class="metrics-grid" aria-label="Shop summary"><?php foreach ($metrics as [$label,$symbol,$value,$unavailable,$hint]): ?><article class="metric-card <?= $value===null?'metric-unavailable':'' ?>"><div class="metric-label"><span><?= e($label) ?></span><?= icon($symbol) ?></div><div class="metric-value <?= $value===null?'text-unavailable':'' ?>"><?php if ($value!==null): ?><?= e((string)$value) ?><?php else: ?><span aria-label="Unavailable">—</span><?php endif; ?></div><p><?= e($value===null?$unavailable:$hint) ?></p></article><?php endforeach; ?></section>
<section class="quick-actions" aria-labelledby="quick-actions-title"><span id="quick-actions-title">Quick actions</span><div><?php foreach ([['Add Product','box'],['New Sale','sale'],['Record Purchase','receipt'],['Adjust Stock','sliders'],['Add Customer','users'],['Add Supplier','truck']] as [$label,$symbol]): ?><?php if($label==='Add Product' && $hasShop && can($user,'products.manage')): ?><a class="button button-quiet" href="<?= e(url('/products/form')) ?>"><?= icon($symbol) ?><?= e($label) ?></a><?php continue; endif; ?><?php if($label==='New Sale' && $hasShop && can($user,'pos.access') && can($user,'sales.create')): ?><a class="button button-quiet" href="<?= e(url('/pos')) ?>"><?= icon($symbol) ?><?= e($label) ?></a><?php continue; endif; ?><?php if($label==='Adjust Stock' && $hasShop && can($user,'inventory.adjust')): ?><a class="button button-quiet" href="<?= e(url('/inventory/adjust')) ?>"><?= icon($symbol) ?><?= e($label) ?></a><?php continue; endif; ?><button type="button" class="button button-quiet" disabled title="<?= e($label) ?> · Coming soon"><?= icon($symbol) ?><?= e($label) ?><span class="sr-only"> — Coming soon</span></button><?php endforeach; ?><?php if ($user['role']==='shop_owner'): ?><a class="button button-primary" href="<?= e(url('/categories')) ?>"><?= icon('folder') ?>Manage categories</a><?php endif; ?></div></section>
<div class="section-toolbar"><div><h2>Shop overview</h2><p>Stock totals are current. The period applies to revenue, profit, movements and sign-ins.</p></div><form method="get" action="index.php" class="period-form"><input type="hidden" name="route" value="/dashboard"><label for="activity-period">Activity period</label><select id="activity-period" name="days"><?php foreach ([7,30,90] as $period): ?><option value="<?= $period ?>" <?= $days===$period?'selected':'' ?>>Last <?= $period ?> days</option><?php endforeach; ?></select><button class="button button-small" type="submit">Apply</button></form></div>
<div class="dashboard-grid">
<section class="surface sales-overview"><header class="surface-header"><h2>Sales &amp; profit overview</h2><span class="subtle-text">Last <?= $days ?> days · Excl. GST</span></header><?php if($d['revenue']!==null): $r=$d['revenue']; ?><div class="table-scroll"><table><thead><tr><th>Revenue category</th><th class="number">Revenue</th><th class="number">Gross profit</th></tr></thead><tbody><tr><td>Product sales</td><td class="number"><?= money($r['product_revenue']) ?></td><td class="number"><?= money($r['product_gross_profit']) ?></td></tr><tr><td>Labour / Service</td><td class="number"><?= money($r['service_revenue']) ?></td><td class="number"><?= money($r['service_gross_profit']) ?></td></tr><tr><td>Total</td><td class="number"><?= money($r['revenue']) ?></td><td class="number"><?= money($r['gross_profit']) ?></td></tr><tr><td colspan="2">Recorded labour expenses</td><td class="number"><?= money($r['labour_expenses']) ?></td></tr><tr><td colspan="2">Net after recorded expenses</td><td class="number"><?= money($r['net_profit']) ?></td></tr></tbody></table></div><footer class="surface-footer"><a href="<?= e(url('/sales/report')) ?>" class="text-link">Revenue &amp; profit report</a></footer><?php else: ?><div class="empty-state compact"><h3><?= e($restricted('finance')??'No sales reporting available') ?></h3><p>Revenue figures appear from posted invoices and labour services.</p></div><?php endif; ?></section>
<section class="surface"><header class="surface-header"><h2>Low-stock alerts</h2><?php if ($d['low_stock_count']!==null): ?><span class="count-badge"><?= (int)$d['low_stock_count'] ?></span><?php endif; ?></header><?php if (isset($d['errors']['stock'])): ?><div class="section-error" role="alert"><?= e($d['errors']['stock']) ?></div><?php elseif ($restricted('stock')): ?><div class="empty-state compact"><?= icon('stock') ?><h3><?= e($restricted('stock')) ?></h3><p>Your shop owner controls access to inventory information.</p></div><?php elseif (!($d['available']['stock'] ?? false)): ?><div class="empty-state compact"><h3>Stock tracking isn’t set up</h3><p>Alerts appear when stock balances and minimum levels are recorded.</p></div><?php elseif (!$d['low_stock']): ?><div class="empty-state compact"><?= icon('check') ?><h3>No low-stock alerts</h3><p><?= $d['balance_count']?'No recorded balance is below its configured minimum.':'Record stock balances and minimum levels to start tracking alerts.' ?></p></div><?php else: ?><div class="table-scroll"><table><thead><tr><th>Product / SKU</th><th class="number">In stock</th><th class="number">Minimum</th></tr></thead><tbody><?php foreach ($d['low_stock'] as $item): ?><tr><td><strong><?= e($item['name']) ?></strong><small><?= e($item['sku']) ?></small></td><td class="number stock-warning"><?= quantity($item['quantity']) ?></td><td class="number"><?= quantity($item['reorder_level']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?><footer class="surface-footer"><span><?php if ($d['untracked_count']): ?><?= (int)$d['untracked_count'] ?> active products have no stock balance yet. <?php endif; ?><?php if(can($user,'inventory.view')): ?><a class="text-link" href="<?= e(url('/inventory')) ?>&amp;stock=low">View inventory</a><?php else: ?>Inventory access is managed by your shop owner<?php endif; ?></span></footer></section>
<section class="surface recent-sales"><header class="surface-header"><h2>Recent sales</h2></header><?php if($d['recent_sales']): ?><div class="table-scroll"><table><thead><tr><th>Invoice</th><th>Customer</th><th class="number">Total</th><th>Status</th></tr></thead><tbody><?php foreach($d['recent_sales'] as $sale): $customer=json_decode($sale['customer_snapshot'],true); ?><tr><td><a href="<?= e(url('/sales/invoice')) ?>&amp;id=<?= (int)$sale['id'] ?>"><?= e($sale['invoice_number']) ?></a><small><?= e(local_datetime($sale['created_at'])) ?></small></td><td><?= e($customer['name']) ?></td><td class="number"><?= money($sale['total']) ?></td><td><?= $sale['cancellation_id']?'Cancelled':'Posted' ?></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><div class="empty-state compact"><h3><?= can($user,'sales.view')?'No recent sales':'Sales history permission required' ?></h3></div><?php endif; ?></section>
<section class="surface recent-movements"><header class="surface-header"><h2>Recent stock movements</h2><span class="subtle-text">Last <?= $days ?> days</span></header><?php if (isset($d['errors']['movements'])): ?><div class="section-error" role="alert"><?= e($d['errors']['movements']) ?></div><?php elseif ($restricted('stock')): ?><div class="empty-state compact"><?= icon('arrows') ?><h3><?= e($restricted('stock')) ?></h3><p>Inventory access is managed by your shop owner.</p></div><?php elseif (!$d['movements']): ?><div class="empty-state compact"><?= icon('arrows') ?><h3>No stock movements in this period</h3><p>Receipts, sales and adjustments will appear as they’re recorded.</p></div><?php else: ?><div class="table-scroll"><table><thead><tr><th>Product</th><th>Movement</th><th class="number">Quantity</th><th>Date / Reference</th></tr></thead><tbody><?php foreach ($d['movements'] as $movement): ?><tr><td><strong><?= e($movement['name']) ?></strong><small><?= e($movement['sku']) ?></small></td><td><?= e(ucwords(str_replace('_',' ',$movement['movement_type']))) ?></td><td class="number <?= $movement['quantity_delta']>0?'quantity-positive':'' ?>"><?= $movement['quantity_delta']>0?'+':'' ?><?= quantity($movement['quantity_delta']) ?> <small><?= e($movement['unit']) ?></small></td><td><?= e(local_datetime($movement['created_at'])) ?><small><?= e(trim(($movement['reference_type'] ?? '').' '.($movement['reference_id'] ?? '')) ?: '—') ?></small></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
<section class="surface outstanding-panel"><header class="surface-header"><h2>Outstanding payments</h2><span class="label-chip">Not set up</span></header><div class="empty-state compact"><?= icon('wallet') ?><h3>Receivables &amp; payables</h3><p>Customer and supplier balances become available with credit billing and payments.</p></div></section>
<section class="surface activity-panel"><header class="surface-header"><h2>Recent activity</h2><span class="subtle-text">Account sign-ins</span></header><?php if (isset($d['errors']['activity'])): ?><div class="section-error" role="alert"><?= e($d['errors']['activity']) ?></div><?php elseif (!$d['activity']): ?><div class="empty-state compact"><?= icon('clock') ?><h3>No recorded activity in this period</h3><p>Latest account sign-ins will appear here.</p></div><?php else: ?><ul class="activity-list"><?php foreach ($d['activity'] as $event): ?><li><span class="activity-dot"></span><div><strong><?= e($event['name']) ?></strong><span>Signed in · <?= e(role_label($event)) ?></span></div><time><?= e(local_datetime($event['last_login_at'])) ?></time></li><?php endforeach; ?></ul><footer class="surface-footer">Latest recorded sign-in for each <?= $user['role']==='shop_owner'?'team member':'account' ?>.</footer><?php endif; ?></section>
</div>
